<?php require __DIR__.'/bootstrap.php'; $rows=$pdo->query('SELECT id,title,subject,grade,description,file_name FROM summaries WHERE published=1 ORDER BY created_at DESC')->fetchAll(); ?><!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="style.css"><title>סיכומים | מחברת פתוחה</title></head><body class="summaries-page"><header><a class="brand" href="index.php">✦ מחברת פתוחה</a><nav><a href="summaries.php" aria-current="page">סיכומים</a><a href="request.php">בקשת סיכום</a></nav></header><main><h1>סיכומים</h1><div class="cards"><?php foreach($rows as $s): ?><article><div class="cover">PDF <b><?=e($s['subject'])?></b></div><small><?=e($s['grade'])?></small><h2><?=e($s['title'])?></h2><p><?=e($s['description'])?></p><a class="download-link" href="uploads/<?=rawurlencode($s['file_name'])?>" target="_blank" rel="noopener">לצפייה ולהורדה ←</a></article><?php endforeach ?><?php if (!$rows): ?><p>עדיין לא פורסמו סיכומים.</p><?php endif ?></div></main><footer>מחברת פתוחה · נבנה באהבה ללמידה · האתר פונה לכל המגדרים</footer></body></html>
